let file = """{"version":3,"file":"workflowShareService-B6vVOyFN.js","names":["$slots","$emit","$t"],"sources":["../../src/components/widget/layout/BaseModalLayout.vue","../../src/components/widget/layout/BaseModalLayout.vue","../../src/platform/workflow/sharing/schemas/shareSchemas.ts","../../src/composables/usePragmaticDragAndDrop.ts","../../src/platform/workflow/sharing/components/ShareAssetThumbnail.vue","../../src/platform/workflow/sharing/components/ShareAssetThumbnail.vue","../../src/platform/workflow/sharing/composables/useAssetSections.ts","../../src/platform/workflow/sharing/components/AssetSectionList.vue","../../src/platform/workflow/sharing/components/AssetSectionList.vue","../../src/platform/workflow/sharing/services/workflowShareService.ts"],"sourcesContent":["<template>\n  <div\n    :class=\"\n      cn(\n        'relative overflow-hidden rounded-2xl border border-border-default bg-base-background shadow-lg',\n        sizeClasses\n      )\n    \"\n    @keydown.esc.capture=\"handleEscape\"\n  >\n    <div\n      class=\"grid size-full transition-[grid-template-columns] duration-300 ease-out\"\n      :style=\"gridStyle\"\n    >\n      <nav\n        class=\"flex h-full flex-col overflow-hidden bg-modal-panel-background\"\n        :inert=\"!showLeftPanel\"\n        :aria-hidden=\"!showLeftPanel\"\n      >\n        <header\n          data-component-id=\"LeftPanelHeader\"\n          class=\"flex h-18 w-full shrink-0 items-center-safe gap-2 pr-3 pl-6\"\n        >\n          <slot name=\"leftPanelHeaderTitle\" />\n          <Button\n            v-if=\"!notMobile && showLeftPanel\"\n            size=\"lg\"\n            class=\"ml-auto w-10 p-0\"\n            :aria-label=\"t('g.hideLeftPanel')\"\n            @click=\"toggleLeftPanel\"\n          >\n            <i class=\"icon-[lucide--panel-left-close]\" />\n          </Button>\n        </header>\n        <slot name=\"leftPanel\" />\n      </nav>\n\n      <div class=\"flex flex-col overflow-hidden bg-base-background\">\n        <header v-if=\"$slots.header\" :class=\"headerClass\">\n          <div :class=\"headerContentClass\">\n            <Button\n              v-if=\"!notMobile && !showLeftPanel\"\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :aria-label=\"t('g.showLeftPanel')\"\n              @click=\"toggleLeftPanel\"\n            >\n              <i class=\"icon-[lucide--panel-left]\" />\n            </Button>\n            <slot name=\"header\" />\n          </div>\n          <slot name=\"header-right-area\" />\n          <template v-if=\"!isRightPanelOpen\">\n            <Button\n              v-if=\"hasRightPanel\"\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :aria-label=\"t('g.showRightPanel')\"\n              @click=\"toggleRightPanel\"\n            >\n              <i class=\"icon-[lucide--panel-right] size-4\" />\n            </Button>\n            <Button\n              size=\"lg\"\n              class=\"w-10\"\n              :variant=\"closeButtonVariant\"\n              :aria-label=\"t('g.closeDialog')\"\n              @click=\"closeDialog\"\n            >\n              <i class=\"pi pi-times\" />\n            </Button>\n          </template>\n        </header>\n\n        <main class=\"flex min-h-0 flex-1 flex-col\">\n          <slot name=\"contentFilter\" />\n          <h2\n            v-if=\"!hasLeftPanel\"\n            class=\"m-0 px-6 pt-2 pb-6 text-2xl capitalize select-none\"\n          >\n            {{ contentTitle }}\n          </h2>\n          <div\n            ref=\"contentContainer\"\n            data-testid=\"base-modal-content\"\n            :class=\"contentContainerClass\"\n          >\n            <slot name=\"content\" />\n          </div>\n        </main>\n      </div>\n\n      <aside\n        v-if=\"hasRightPanel\"\n        class=\"overflow-hidden\"\n        :inert=\"!isRightPanelOpen\"\n        :aria-hidden=\"!isRightPanelOpen\"\n      >\n        <div\n          class=\"flex h-full w-72 min-w-72 flex-col bg-modal-panel-background\"\n        >\n          <header\n            data-component-id=\"RightPanelHeader\"\n            class=\"flex h-18 shrink-0 items-center gap-2 px-6\"\n          >\n            <h2\n              v-if=\"rightPanelTitle\"\n              class=\"flex-1 text-base font-semibold select-none\"\n            >\n              {{ rightPanelTitle }}\n            </h2>\n            <div v-else class=\"flex-1\">\n              <slot name=\"rightPanelHeaderTitle\" />\n            </div>\n            <slot name=\"rightPanelHeaderActions\" />\n            <Button\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :aria-label=\"t('g.hideRightPanel')\"\n              @click=\"toggleRightPanel\"\n            >\n              <i class=\"icon-[lucide--panel-right-close] size-4\" />\n            </Button>\n            <Button\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :variant=\"closeButtonVariant\"\n              :aria-label=\"t('g.closeDialog')\"\n              @click=\"closeDialog\"\n            >\n              <i class=\"pi pi-times\" />\n            </Button>\n          </header>\n          <div class=\"min-h-0 flex-1 overflow-y-auto\">\n            <slot name=\"rightPanel\" />\n          </div>\n        </div>\n      </aside>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useBreakpoints } from '@vueuse/core'\nimport { computed, inject, ref, useSlots, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\nimport { OnCloseKey } from '@/types/widgetTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\n\nconst SIZE_CLASSES = {\n  md: 'h-[80vh] w-[90vw] max-w-[1400px]',\n  lg: 'h-[80vh] max-h-[1026px] w-[90vw] max-w-[1280px] min-[1450px]:max-w-[1724px] min-[3000px]:max-h-[1320px] min-[3000px]:max-w-[2200px]'\n} as const\n\ntype ModalSize = keyof typeof SIZE_CLASSES\ntype ContentPadding = 'default' | 'compact' | 'none'\ntype HeaderPadding = 'default' | 'symmetric'\n\nconst {\n  contentTitle,\n  rightPanelTitle,\n  size = 'lg',\n  leftPanelWidth = '14rem',\n  contentPadding = 'default',\n  headerPadding = 'default',\n  closeButtonVariant\n} = defineProps<{\n  contentTitle: string\n  rightPanelTitle?: string\n  size?: ModalSize\n  leftPanelWidth?: string\n  contentPadding?: ContentPadding\n  headerPadding?: HeaderPadding\n  closeButtonVariant?: ButtonVariants['variant']\n}>()\n\nconst sizeClasses = computed(() => SIZE_CLASSES[size])\n\nconst isRightPanelOpen = defineModel<boolean>('rightPanelOpen', {\n  default: false\n})\n\nconst slots = useSlots()\nconst hasLeftPanel = computed(() => !!slots.leftPanel)\nconst hasRightPanel = computed(() => !!slots.rightPanel)\n\nconst BREAKPOINTS = { md: 880 }\n\nconst closeDialog = inject(OnCloseKey, () => {})\n\nconst breakpoints = useBreakpoints(BREAKPOINTS)\nconst notMobile = breakpoints.greater('md')\n\nconst isLeftPanelOpen = ref<boolean>(true)\nconst mobileMenuOpen = ref<boolean>(false)\nconst contentContainer = ref<HTMLElement | null>(null)\n\nwatch(notMobile, (isDesktop) => {\n  if (!isDesktop) {\n    mobileMenuOpen.value = false\n  }\n})\n\nconst showLeftPanel = computed(() => {\n  const shouldShow = notMobile.value\n    ? isLeftPanelOpen.value\n    : mobileMenuOpen.value\n  return shouldShow\n})\n\nconst headerClass = computed(() =>\n  cn(\n    'flex w-full items-center justify-between gap-2',\n    headerPadding === 'symmetric' ? 'px-6 py-5' : 'h-18 px-6'\n  )\n)\n\nconst headerContentClass = computed(() =>\n  cn(\n    'flex min-w-0 flex-1 gap-2',\n    headerPadding === 'symmetric' && 'min-h-10 items-center'\n  )\n)\n\nconst contentContainerClass = computed(() =>\n  cn(\n    'flex scrollbar-custom min-h-0 flex-1 flex-col overflow-y-auto',\n    contentPadding === 'default' && 'px-6 pt-0 pb-10',\n    contentPadding === 'compact' && 'px-6 pt-0 pb-2'\n  )\n)\n\nconst gridStyle = computed(() => ({\n  gridTemplateColumns: hasRightPanel.value\n    ? `${hasLeftPanel.value && showLeftPanel.value ? leftPanelWidth : '0rem'} 1fr ${isRightPanelOpen.value ? '18rem' : '0rem'}`\n    : `${hasLeftPanel.value && showLeftPanel.value ? leftPanelWidth : '0rem'} 1fr`\n}))\n\nconst toggleLeftPanel = () => {\n  if (notMobile.value) {\n    isLeftPanelOpen.value = !isLeftPanelOpen.value\n  } else {\n    mobileMenuOpen.value = !mobileMenuOpen.value\n  }\n}\n\nconst toggleRightPanel = () => {\n  isRightPanelOpen.value = !isRightPanelOpen.value\n}\n\nfunction handleEscape(event: KeyboardEvent) {\n  const target = event.target\n  if (!(target instanceof HTMLElement)) return\n  if (\n    target instanceof HTMLInputElement ||\n    target instanceof HTMLTextAreaElement ||\n    target instanceof HTMLSelectElement ||\n    target.isContentEditable\n  ) {\n    return\n  }\n  if (isRightPanelOpen.value) {\n    event.stopPropagation()\n    isRightPanelOpen.value = false\n  }\n}\n\ndefineExpose({\n  getContentScrollTop: () => contentContainer.value?.scrollTop ?? 0,\n  setContentScrollTop: (scrollTop: number) => {\n    if (contentContainer.value) contentContainer.value.scrollTop = scrollTop\n  }\n})\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        'relative overflow-hidden rounded-2xl border border-border-default bg-base-background shadow-lg',\n        sizeClasses\n      )\n    \"\n    @keydown.esc.capture=\"handleEscape\"\n  >\n    <div\n      class=\"grid size-full transition-[grid-template-columns] duration-300 ease-out\"\n      :style=\"gridStyle\"\n    >\n      <nav\n        class=\"flex h-full flex-col overflow-hidden bg-modal-panel-background\"\n        :inert=\"!showLeftPanel\"\n        :aria-hidden=\"!showLeftPanel\"\n      >\n        <header\n          data-component-id=\"LeftPanelHeader\"\n          class=\"flex h-18 w-full shrink-0 items-center-safe gap-2 pr-3 pl-6\"\n        >\n          <slot name=\"leftPanelHeaderTitle\" />\n          <Button\n            v-if=\"!notMobile && showLeftPanel\"\n            size=\"lg\"\n            class=\"ml-auto w-10 p-0\"\n            :aria-label=\"t('g.hideLeftPanel')\"\n            @click=\"toggleLeftPanel\"\n          >\n            <i class=\"icon-[lucide--panel-left-close]\" />\n          </Button>\n        </header>\n        <slot name=\"leftPanel\" />\n      </nav>\n\n      <div class=\"flex flex-col overflow-hidden bg-base-background\">\n        <header v-if=\"$slots.header\" :class=\"headerClass\">\n          <div :class=\"headerContentClass\">\n            <Button\n              v-if=\"!notMobile && !showLeftPanel\"\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :aria-label=\"t('g.showLeftPanel')\"\n              @click=\"toggleLeftPanel\"\n            >\n              <i class=\"icon-[lucide--panel-left]\" />\n            </Button>\n            <slot name=\"header\" />\n          </div>\n          <slot name=\"header-right-area\" />\n          <template v-if=\"!isRightPanelOpen\">\n            <Button\n              v-if=\"hasRightPanel\"\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :aria-label=\"t('g.showRightPanel')\"\n              @click=\"toggleRightPanel\"\n            >\n              <i class=\"icon-[lucide--panel-right] size-4\" />\n            </Button>\n            <Button\n              size=\"lg\"\n              class=\"w-10\"\n              :variant=\"closeButtonVariant\"\n              :aria-label=\"t('g.closeDialog')\"\n              @click=\"closeDialog\"\n            >\n              <i class=\"pi pi-times\" />\n            </Button>\n          </template>\n        </header>\n\n        <main class=\"flex min-h-0 flex-1 flex-col\">\n          <slot name=\"contentFilter\" />\n          <h2\n            v-if=\"!hasLeftPanel\"\n            class=\"m-0 px-6 pt-2 pb-6 text-2xl capitalize select-none\"\n          >\n            {{ contentTitle }}\n          </h2>\n          <div\n            ref=\"contentContainer\"\n            data-testid=\"base-modal-content\"\n            :class=\"contentContainerClass\"\n          >\n            <slot name=\"content\" />\n          </div>\n        </main>\n      </div>\n\n      <aside\n        v-if=\"hasRightPanel\"\n        class=\"overflow-hidden\"\n        :inert=\"!isRightPanelOpen\"\n        :aria-hidden=\"!isRightPanelOpen\"\n      >\n        <div\n          class=\"flex h-full w-72 min-w-72 flex-col bg-modal-panel-background\"\n        >\n          <header\n            data-component-id=\"RightPanelHeader\"\n            class=\"flex h-18 shrink-0 items-center gap-2 px-6\"\n          >\n            <h2\n              v-if=\"rightPanelTitle\"\n              class=\"flex-1 text-base font-semibold select-none\"\n            >\n              {{ rightPanelTitle }}\n            </h2>\n            <div v-else class=\"flex-1\">\n              <slot name=\"rightPanelHeaderTitle\" />\n            </div>\n            <slot name=\"rightPanelHeaderActions\" />\n            <Button\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :aria-label=\"t('g.hideRightPanel')\"\n              @click=\"toggleRightPanel\"\n            >\n              <i class=\"icon-[lucide--panel-right-close] size-4\" />\n            </Button>\n            <Button\n              size=\"lg\"\n              class=\"w-10 p-0\"\n              :variant=\"closeButtonVariant\"\n              :aria-label=\"t('g.closeDialog')\"\n              @click=\"closeDialog\"\n            >\n              <i class=\"pi pi-times\" />\n            </Button>\n          </header>\n          <div class=\"min-h-0 flex-1 overflow-y-auto\">\n            <slot name=\"rightPanel\" />\n          </div>\n        </div>\n      </aside>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useBreakpoints } from '@vueuse/core'\nimport { computed, inject, ref, useSlots, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\nimport { OnCloseKey } from '@/types/widgetTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\n\nconst SIZE_CLASSES = {\n  md: 'h-[80vh] w-[90vw] max-w-[1400px]',\n  lg: 'h-[80vh] max-h-[1026px] w-[90vw] max-w-[1280px] min-[1450px]:max-w-[1724px] min-[3000px]:max-h-[1320px] min-[3000px]:max-w-[2200px]'\n} as const\n\ntype ModalSize = keyof typeof SIZE_CLASSES\ntype ContentPadding = 'default' | 'compact' | 'none'\ntype HeaderPadding = 'default' | 'symmetric'\n\nconst {\n  contentTitle,\n  rightPanelTitle,\n  size = 'lg',\n  leftPanelWidth = '14rem',\n  contentPadding = 'default',\n  headerPadding = 'default',\n  closeButtonVariant\n} = defineProps<{\n  contentTitle: string\n  rightPanelTitle?: string\n  size?: ModalSize\n  leftPanelWidth?: string\n  contentPadding?: ContentPadding\n  headerPadding?: HeaderPadding\n  closeButtonVariant?: ButtonVariants['variant']\n}>()\n\nconst sizeClasses = computed(() => SIZE_CLASSES[size])\n\nconst isRightPanelOpen = defineModel<boolean>('rightPanelOpen', {\n  default: false\n})\n\nconst slots = useSlots()\nconst hasLeftPanel = computed(() => !!slots.leftPanel)\nconst hasRightPanel = computed(() => !!slots.rightPanel)\n\nconst BREAKPOINTS = { md: 880 }\n\nconst closeDialog = inject(OnCloseKey, () => {})\n\nconst breakpoints = useBreakpoints(BREAKPOINTS)\nconst notMobile = breakpoints.greater('md')\n\nconst isLeftPanelOpen = ref<boolean>(true)\nconst mobileMenuOpen = ref<boolean>(false)\nconst contentContainer = ref<HTMLElement | null>(null)\n\nwatch(notMobile, (isDesktop) => {\n  if (!isDesktop) {\n    mobileMenuOpen.value = false\n  }\n})\n\nconst showLeftPanel = computed(() => {\n  const shouldShow = notMobile.value\n    ? isLeftPanelOpen.value\n    : mobileMenuOpen.value\n  return shouldShow\n})\n\nconst headerClass = computed(() =>\n  cn(\n    'flex w-full items-center justify-between gap-2',\n    headerPadding === 'symmetric' ? 'px-6 py-5' : 'h-18 px-6'\n  )\n)\n\nconst headerContentClass = computed(() =>\n  cn(\n    'flex min-w-0 flex-1 gap-2',\n    headerPadding === 'symmetric' && 'min-h-10 items-center'\n  )\n)\n\nconst contentContainerClass = computed(() =>\n  cn(\n    'flex scrollbar-custom min-h-0 flex-1 flex-col overflow-y-auto',\n    contentPadding === 'default' && 'px-6 pt-0 pb-10',\n    contentPadding === 'compact' && 'px-6 pt-0 pb-2'\n  )\n)\n\nconst gridStyle = computed(() => ({\n  gridTemplateColumns: hasRightPanel.value\n    ? `${hasLeftPanel.value && showLeftPanel.value ? leftPanelWidth : '0rem'} 1fr ${isRightPanelOpen.value ? '18rem' : '0rem'}`\n    : `${hasLeftPanel.value && showLeftPanel.value ? leftPanelWidth : '0rem'} 1fr`\n}))\n\nconst toggleLeftPanel = () => {\n  if (notMobile.value) {\n    isLeftPanelOpen.value = !isLeftPanelOpen.value\n  } else {\n    mobileMenuOpen.value = !mobileMenuOpen.value\n  }\n}\n\nconst toggleRightPanel = () => {\n  isRightPanelOpen.value = !isRightPanelOpen.value\n}\n\nfunction handleEscape(event: KeyboardEvent) {\n  const target = event.target\n  if (!(target instanceof HTMLElement)) return\n  if (\n    target instanceof HTMLInputElement ||\n    target instanceof HTMLTextAreaElement ||\n    target instanceof HTMLSelectElement ||\n    target.isContentEditable\n  ) {\n    return\n  }\n  if (isRightPanelOpen.value) {\n    event.stopPropagation()\n    isRightPanelOpen.value = false\n  }\n}\n\ndefineExpose({\n  getContentScrollTop: () => contentContainer.value?.scrollTop ?? 0,\n  setContentScrollTop: (scrollTop: number) => {\n    if (contentContainer.value) contentContainer.value.scrollTop = scrollTop\n  }\n})\n</script>\n","import { zAssetInfo, zHubProfile } from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\nconst zComfyHubProfile = zHubProfile\n  .pick({ username: true, description: true })\n  .extend({\n    name: zHubProfile.shape.display_name,\n    coverImageUrl: z.string().nullish(),\n    profilePictureUrl: zHubProfile.shape.avatar_url.nullish()\n  })\n\nexport type ComfyHubProfile = z.infer<typeof zComfyHubProfile>\n\nexport const zPublishRecordResponse = z.object({\n  workflow_id: z.string(),\n  share_id: z.string().nullable(),\n  listed: z.boolean(),\n  publish_time: z.string().nullable(),\n  assets: z.array(zAssetInfo).optional()\n})\n\n/**\n * Strips path separators and control characters from a workflow name to prevent\n * path traversal when the name is later used as part of a file path.\n */\nfunction sanitizeWorkflowName(name: string): string {\n  return name\n    .replaceAll(/[/\\\\:]/g, '_')\n    .slice(0, 200)\n    .trim()\n}\n\nexport const zSharedWorkflowResponse = z.object({\n  share_id: z.string(),\n  workflow_id: z.string(),\n  name: z.string().transform(sanitizeWorkflowName),\n  listed: z.boolean(),\n  publish_time: z.string().nullable(),\n  workflow_json: z.record(z.string(), z.unknown()),\n  assets: z.array(zAssetInfo)\n})\n\nexport const zHubProfileResponse = z.preprocess((data) => {\n  if (!data || typeof data !== 'object') return data\n  const d = data as Record<string, unknown>\n  return {\n    username: d.username,\n    name: d.name ?? d.display_name,\n    description: d.description,\n    coverImageUrl: d.coverImageUrl ?? d.cover_image_url,\n    profilePictureUrl:\n      d.profilePictureUrl ?? d.profile_picture_url ?? d.avatar_url\n  }\n}, zComfyHubProfile)\n\nexport const zHubAssetUploadUrlResponse = z\n  .object({\n    upload_url: z.string(),\n    public_url: z.string(),\n    token: z.string()\n  })\n  .transform((response) => ({\n    uploadUrl: response.upload_url,\n    publicUrl: response.public_url,\n    token: response.token\n  }))\n\nexport const zHubWorkflowPublishResponse = z.object({\n  share_id: z.string(),\n  workflow_id: z.string(),\n  thumbnail_type: z.enum(['image', 'video', 'image_comparison']).optional()\n})\n\nconst zHubLabelInfo = z.object({\n  name: z.string(),\n  display_name: z.string(),\n  type: z.enum(['tag', 'model', 'custom_node'])\n})\n\nexport const zHubLabelListResponse = z.object({\n  labels: z.array(zHubLabelInfo)\n})\n","import {\n  draggable,\n  dropTargetForElements\n} from '@atlaskit/pragmatic-drag-and-drop/element/adapter'\nimport { onBeforeUnmount, onMounted, toValue, watch } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\nexport function usePragmaticDroppable(\n  dropTargetElement: MaybeRefOrGetter<HTMLElement | null>,\n  options: Omit<Parameters<typeof dropTargetForElements>[0], 'element'>\n) {\n  let cleanup = () => {}\n\n  onMounted(() => {\n    cleanup = watch(\n      () => toValue(dropTargetElement),\n      (element, _previous, onCleanup) => {\n        if (!element) return\n        onCleanup(dropTargetForElements({ element, ...options }))\n      },\n      { immediate: true, flush: 'post' }\n    )\n  })\n\n  onBeforeUnmount(() => {\n    cleanup()\n  })\n}\n\nexport function usePragmaticDraggable(\n  draggableElement: MaybeRefOrGetter<HTMLElement | null>,\n  options: Omit<Parameters<typeof draggable>[0], 'element'>\n) {\n  let cleanup = () => {}\n\n  onMounted(() => {\n    const element = toValue(draggableElement)\n\n    if (!element) {\n      return\n    }\n\n    cleanup = draggable({\n      element,\n      ...options\n    })\n    // TODO: Change to onScopeDispose\n  })\n\n  onBeforeUnmount(() => {\n    cleanup()\n  })\n}\n","<template>\n  <div\n    class=\"relative flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-md bg-muted\"\n  >\n    <Skeleton\n      v-if=\"normalizedPreviewUrl && isLoading\"\n      class=\"absolute inset-0\"\n    />\n    <img\n      v-if=\"normalizedPreviewUrl && !error\"\n      :src=\"normalizedPreviewUrl\"\n      :alt=\"name\"\n      :class=\"\n        cn(\n          'size-full object-cover transition-opacity duration-200',\n          isReady ? 'opacity-100' : 'opacity-0'\n        )\n      \"\n      @error=\"\n        $emit('thumbnailError', { name, previewUrl: normalizedPreviewUrl })\n      \"\n    />\n    <i\n      v-if=\"!normalizedPreviewUrl || error\"\n      class=\"icon-[lucide--image] size-4 text-muted-foreground\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport { useImageQuiet } from '@/composables/useImageQuiet'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { name, previewUrl } = defineProps<{\n  name: string\n  previewUrl: string | null | undefined\n}>()\n\ndefineEmits<{\n  thumbnailError: [{ name: string; previewUrl: string | null }]\n}>()\n\nconst normalizedPreviewUrl = computed(() => {\n  if (typeof previewUrl !== 'string' || previewUrl.length === 0) return null\n  try {\n    const url = new URL(previewUrl, window.location.origin)\n    if (\n      !url.origin.includes('googleapis') &&\n      url.searchParams.has('filename') &&\n      !url.searchParams.has('res')\n    )\n      url.searchParams.set('res', '256')\n    return url.toString()\n  } catch {\n    return previewUrl\n  }\n})\n\nconst imageOptions = computed(() => ({\n  src: normalizedPreviewUrl.value ?? ''\n}))\n\nconst { isReady, isLoading, error } = useImageQuiet(imageOptions)\n</script>\n","<template>\n  <div\n    class=\"relative flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-md bg-muted\"\n  >\n    <Skeleton\n      v-if=\"normalizedPreviewUrl && isLoading\"\n      class=\"absolute inset-0\"\n    />\n    <img\n      v-if=\"normalizedPreviewUrl && !error\"\n      :src=\"normalizedPreviewUrl\"\n      :alt=\"name\"\n      :class=\"\n        cn(\n          'size-full object-cover transition-opacity duration-200',\n          isReady ? 'opacity-100' : 'opacity-0'\n        )\n      \"\n      @error=\"\n        $emit('thumbnailError', { name, previewUrl: normalizedPreviewUrl })\n      \"\n    />\n    <i\n      v-if=\"!normalizedPreviewUrl || erro