sync function getPublishStatus(\n    workflowPath: string\n  ): Promise<WorkflowPublishStatus> {\n    const response = await api.fetchApi(\n      `/userdata/${encodeURIComponent(workflowPath)}/publish`\n    )\n    if (!response.ok) {\n      if (response.status === 404) return UNPUBLISHED\n      throw new Error(\n        `Failed to fetch publish status: ${response.status} ${response.statusText}`\n      )\n    }\n\n    const json = await response.json()\n    const record = decodePublishRecord(json)\n    if (!record || !record.shareId || !record.publishedAt) return UNPUBLISHED\n\n    let prefill: PublishPrefill | null = record.prefill\n    if (shouldFetchPrefill(record.listed, prefill)) {\n      try {\n        prefill = await fetchHubWorkflowPrefill(record.shareId)\n      } catch {\n        prefill = null\n      }\n    }\n\n    return {\n      isPublished: true,\n      shareId: record.shareId,\n      shareUrl: normalizeShareUrl(record.shareId),\n      publishedAt: record.publishedAt,\n      prefill\n    }\n  }\n\n  async function getShareableAssets(\n    includingPublic = false\n  ): Promise<AssetInfo[]> {\n    if (!app.isGraphReady) return []\n\n    const graph = app.rootGraph\n    const { output } = await app.graphToPrompt(graph)\n    const { assets } = await api.getShareableAssets(output)\n\n    return includingPublic ? assets : assets.filter((asset) => !asset.public)\n  }\n\n  async function getSharedWorkflow(\n    shareId: string\n  ): Promise<SharedWorkflowPayload> {\n    let response: Response\n    try {\n      response = await api.fetchApi(\n        `/workflows/published/${encodeURIComponent(shareId)}`\n      )\n    } catch {\n      throw new SharedWorkflowLoadError(\n        null,\n        'Failed to load shared workflow: network error'\n      )\n    }\n\n    if (!response.ok) {\n      throw new SharedWorkflowLoadError(response.status)\n    }\n\n    const workflow = decodeSharedWorkflowPayload(await response.json())\n    if (!workflow) {\n      throw new Error('Failed to load shared workflow: invalid response')\n    }\n\n    return workflow\n  }\n\n  async function importPublishedAssets(\n    assetIds: string[],\n    shareId?: string\n  ): Promise<void> {\n    const body: ImportPublishedAssetsRequest = {\n      published_asset_ids: assetIds,\n      ...(shareId ? { share_id: shareId } : {})\n    }\n\n    const response = await api.fetchApi('/assets/import', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(body)\n    })\n\n    if (!response.ok) {\n      throw new Error(`Failed to import assets: ${response.status}`)\n    }\n\n    await useAssetsStore().inputAssets.invalidate()\n  }\n\n  return {\n    publishWorkflow,\n    getPublishStatus,\n    getShareableAssets,\n    getSharedWorkflow,\n    importPublishedAssets\n  }\n}\n\nfunction shouldFetchPrefill(listed: boolean, prefill: PublishPrefill | null) {\n  return listed && !prefill\n}\n"],"mappings":"i+DAwJA,GAAM,CAAE,KAAM,GAAQ,EAEhB,EAAe,CACnB,GAAI,mCACJ,GAAI,qIACN,EAwBM,EAAc,MAAe,EAAa,EAAA,KAAK,EAE/C,EAAmB,EAAoB,EAAC,gBAE7C,EAEK,EAAQ,EAAS,EACjB,EAAe,MAAe,CAAC,CAAC,EAAM,SAAS,EAC/C,EAAgB,MAAe,CAAC,CAAC,EAAM,UAAU,EAEjD,EAAc,CAAE,GAAI,GAAI,EAExB,EAAc,EAAO,MAAkB,CAAC,CAAC,EAGzC,EADc,GAAe,CACjB,CAAA,CAAY,QAAQ,IAAI,EAEpC,EAAkB,EAAa,EAAI,EACnC,EAAiB,EAAa,EAAK,EACnC,EAAmB,EAAwB,IAAI,EAErD,EAAM,EAAY,GAAc,CACzB,IACH,EAAe,MAAQ,GAE3B,CAAC,EAED,IAAM,EAAgB,MACD,EAAU,MACzB,EAAgB,MAChB,EAAe,KAEpB,EAEK,EAAc,MAClB,EACE,iDACA,EAAA,gBAAkB,YAAc,YAAc,WAChD,CACF,EAEM,EAAqB,MACzB,EACE,4BACA,EAAA,gBAAkB,aAAe,uBACnC,CACF,EAEM,EAAwB,MAC5B,EACE,gEACA,EAAA,iBAAmB,WAAa,kBAChC,EAAA,iBAAmB,WAAa,gBAClC,CACF,EAEM,EAAY,OAAgB,CAChC,oBAAqB,EAAc,MAC/B,GAAG,EAAa,OAAS,EAAc,MAAQ,EAAA,eAAiB,OAAO,OAAO,EAAiB,MAAQ,QAAU,SACjH,GAAG,EAAa,OAAS,EAAc,MAAQ,EAAA,eAAiB,OAAO,KAC7E,EAAE,EAEI,oBAAwB,CACxB,EAAU,MACZ,EAAgB,MAAQ,CAAC,EAAgB,MAEzC,EAAe,MAAQ,CAAC,EAAe,KAE3C,EAEM,qBAAyB,CAC7B,EAAiB,MAAQ,CAAC,EAAiB,KAC7C,EAEA,SAAS,aAAa,EAAsB,CAC1C,IAAM,EAAS,EAAM,OACf,aAAkB,cAEtB